def dedupe(xs):
    """Remove duplicates from a list while preserving first-occurrence order.

    Works with any hashable elements. If elements are unhashable,
    falls back to an O(n^2) comparison-based approach.
    """
    if not xs:
        return []

    seen = set()
    result = []
    try:
        for x in xs:
            if x not in seen:
                seen.add(x)
                result.append(x)
    except TypeError:
        # Fallback for unhashable elements
        result = []
        for x in xs:
            if x not in result:
                result.append(x)
    return result
